#include<bits/stdc++.h>
using namespace std;
const int MAXN = 500+5;
int n, m, mod;
inline int mod_add(int a, int b) { return (a += b) >= mod ? a - mod : a; }
inline int mod_sub(int a, int b) { return (a -= b) < 0 ? a + mod : a; }
int power(int a, int b) {
    int res = 1;
    while (b) {
        if (b & 1) res = (long long)res * a % mod;
        a = (long long)a * a % mod;
        b >>= 1;
    }
    return res;
}
int fact[2005], invfact[2005];
void precompute(int limit) {
    fact[0] = 1;
    for (int i = 1; i <= limit; ++i) fact[i] = (long long)fact[i-1] * i % mod;
    invfact[limit] = power(fact[limit], mod - 2);
    for (int i = limit - 1; i >= 0; --i) invfact[i] = (long long)invfact[i+1] * (i+1) % mod;
}
int comb(int n, int k) {
    if (n < 0 || k < 0 || n < k) return 0;
    return (long long)fact[n] * invfact[n-k] % mod * invfact[k] % mod;
}
int tri(int x) { return x * (x + 1) / 2; }
vector<int> multiply(const vector<int> &A, const vector<int> &B) {
    vector<int> C(A.size() + B.size() - 1, 0);
    for (int i = 0; i < (int)A.size(); ++i)
        for (int j = 0; j < (int)B.size(); ++j)
            C[i+j] = mod_add(C[i+j], (long long)A[i] * B[j] % mod);
    return C;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> m >> n >> mod;
    precompute(m << 1);
    vector<int> F(n+1), G(n+1);
    F[0] = 1;
    for (int i = 1; i <= n; ++i) {
        int sum = 0;
        for (int j = 0; j < i; ++j)
            sum = mod_add(sum, (long long)F[j] * F[i-1-j] % mod * comb(i-1, j) % mod);
        F[i] = (long long)sum * (i+1) % mod;
    }
    for (int i = 1; i <= n; ++i) {
        int sum = 0;
        for (int j = 0; j < i; ++j) {
            int term = ((long long)2 * F[j] * G[i-1-j] % mod * comb(i-1, j) % mod * (i+1) % mod
                       + (long long)comb(i-1, j) * (tri(j) + tri(i-1-j)) % mod * F[j] % mod * F[i-1-j] % mod) % mod;
            sum = mod_add(sum, term);
        }
        G[i] = sum;
    }
    F[0] = 0;
    for (int i = 0; i <= n; ++i) {
        G[i] = (long long)G[i] * invfact[i] % mod;
        F[i] = (long long)F[i] * invfact[i] % mod;
    }
    int ans = 0;
    for (int i = 1; i <= m - n + 1; ++i) {
        ans = mod_add(ans, (long long)G[n] * comb(m - n, i) % mod * fact[n] % mod * i % mod);
        G = multiply(G, F);
        G.resize(n + 1);
    }
    cout << ans << '\n';
    return 0;
}
